      "B": "Une dysphagie est dite paradoxale si elle prédomine sur les solides",
      "C": "Une dysphagie intermittente est en faveur d'une cause organique",
      "D": "Le transit œsogastroduodénal fait partie du bilan de première intention devant une dysphagie",
