    "question": "La dysphagie progressive associée à l'odynophagie c'est un signe évocateur en 1ère intention à :",
    "propositions": {
      "A": "Cancer du tiers moyen de l'œsophage",
      "B": "Œsophagite caustique suite à l'ingestion de l'essence",
      "C": "Œsophagite due à des levures chez un patient immunodéprimé",
      "D": "Œsophagite peptique compliquant un RGO",
      "E": "Cancer du tiers inférieur de l'œsophage"
    },
    "bonnes_reponses": [
      "A",
      "E"
    ],
    "explication": "L'association d'une dysphagie progressive et d'une odynophagie chez l'adulte fait suspecter en première intention un cancer de l'œsophage (tiers moyen ou inférieur).",
    "justifications": {
      "A": "Vrai. Le cancer du tiers moyen de l'œsophage est une cause fréquente d'obstacle tumoral progressif.",
      "B": "Faux. L'ingestion caustique a un début suraigu accidentel évident.",
      "C": "Faux. L'œsophagite candidosique donne une odynophagie vive isolée chez l'immunodéprimé.",
      "D": "Faux. L'œsophagite peptique donne principalement un pyrosis ; la dysphagie n'apparaît qu'en cas de sténose peptique.",
      "E": "Vrai. L'adénocarcinome ou épidermoïde du tiers inférieur se manifeste typiquement ainsi.",
      "_synthese": "Dysphagie progressive d'aggravation continue = néoplasie œsophagienne jusqu'à preuve histologique du contraire.",
      "_remarque": "L'endoscopie avec biopsies multiples est l'examen diagnostique clé."
    }
