      "C": "Faux. L'EBO est asymptomatique par lui-même.",
      "D": "Vrai. Surveillance endoscopique avec protocole de biopsies pour dépister la dysplasie.",
      "E": "Vrai. L'ulcère de Barrett peut se développer sur la muqueuse métaplasique.",
