      "_synthese": "En imagerie de la LVBP : Échographie en 1ère ligne (sensibilité imparfaite) -> Bili-IRM non invasive de confirmation -> CPRE interventionnelle.",
      "_remarque": "L'écho-endoscopie et la cholangio-IRM ont une sensibilité et une spécificité diagnostique comparables (> 95%)."
