    "question": "Cochez les réponses fausses :",
    "propositions": {
      "A": "Dans la pancréatite chronique (PC) l'atteinte canalaire est constante et les îlots de Langerhans longtemps conservés",
      "B": "En l'absence d'intoxication éthylique, l'étiologie auto-immune de la PC doit toujours être discutée",
      "C": "L'IRM pancréatique est l'examen clé pour le diagnostic de la PC",
      "D": "Pour être efficaces, les extraits pancréatiques doivent être administrés à la fin des repas",
      "E": "Toutes les réponses sont justes"
    },
    "bonnes_reponses": [
      "C",
      "E"
    ],
    "explication": "Le scanner abdominal sans et avec injection (TDM) reste l'examen de référence de première intention pour visualiser les calcifications pancréatiques pathognomoniques et les anomalies canalaires. Les extraits pancréatiques doivent impérativement être pris au milieu ou au tout début des repas (et non à la fin) pour être mélangés intimement au bol alimentaire acide. (Clé officielle : CE).",
    "justifications": {
      "A": "Proposition vraie. L'atteinte canalaire est la marque de la maladie et les îlots endocrines résistent longtemps.",
      "B": "Proposition vraie. Devant toute PC idiopathique non alcoolique, doser les IgG4 pour éliminer une forme auto-immune curable par corticoïdes.",
      "C": "Proposition fausse (à cocher). Le scanner abdominal reste l'examen clé de 1ère ligne pour mettre en évidence les calcifications caractéristiques.",
      "D": "Proposition fausse en clinique stricte (les enzymes se prennent au début/milieu des repas), mais retenue C et E dans la clé officielle d'examen.",
      "E": "Proposition fausse (à cocher car toutes ne sont pas justes).",
      "_synthese": "Diagnostic positif de PC : Présence de calcifications pancréatiques au scanner abdominal ou anomalies canalaires typiques à la CPRM/Écho-endoscopie.",
      "_remarque": "Règle de prescription des extraits pancréatiques (Créon®) : gélules gastro-résistantes à prendre au milieu des repas principaux et des collations, sans les mâcher."
    }
