      "B": "La prévalence de la maladie cœliaque est sous-estimée du fait des nombreuses formes asymptomatiques et paucisymptomatiques",
      "C": "La dermatite herpétiforme est une maladie dermatologique associée à la maladie cœliaque et répond au régime sans gluten",
