    "explication": "Le diagnostic d'une hernie de l'aine est purement CLINIQUE (inspection et palpation debout et couché lors d'efforts de poussée : tuméfaction réductible, impulsive et expansive à la toux). Aucun examen d'imagerie n'est nécessaire dans les formes simples. La hernie crurale siège au-dessous de l'arcade crurale à la racine de la cuisse, médiale par rapport aux vaisseaux fémoraux (dans l'infundibulum crural). Le diagnostic d'étranglement herniaire est également clinique d'extrême urgence sans perdre de temps avec un scanner.",
