    "question": "Quelles propositions sont vraies à propos des hernies inguinales obliques externes (HIOE) :",
    "propositions": {
      "A": "Le collet de la hernie est situé au-dessus de la ligne de Malgaigne",
      "B": "Le collet de la hernie est situé au-dessous de la ligne de Malgaigne",
      "C": "Les vaisseaux épigastriques sont en dehors de la hernie",
      "D": "Les vaisseaux épigastriques sont en dedans de la hernie",
      "E": "Le trajet suit le cordon spermatique"
    },
    "bonnes_reponses": [
      "A",
      "D",
      "E"
    ],
    "explication": "La hernie inguinale oblique externe (indirecte) franchit l'orifice inguinal profond situé EN DEHORS des vaisseaux épigastriques inférieurs (donc les vaisseaux épigastriques sont EN DEDANS du collet herniaire). Elle chemine dans le canal inguinal le long du cordon spermatique (vers la bourse). Son collet est situé AU-DESSUS de la ligne de Malgaigne (arcade crurale).",
    "justifications": {
      "A": "Vrai. Toutes les hernies inguinales sont situées au-dessus de la ligne de Malgaigne.",
      "B": "Faux. Au-dessous de la ligne de Malgaigne correspond à la hernie crurale.",
      "C": "Faux. Les vaisseaux épigastriques sont en dedans de l'orifice inguinal profond.",
      "D": "Vrai. Les vaisseaux épigastriques bordent médialement le collet de l'HIOE.",
      "E": "Vrai. Elle emprunte le canal inguinal avec les éléments du cordon spermatique.",
      "_synthese": "Repères anatomiques : HIOE (indirecte) = au-dessus de l'arcade, en dehors des vaisseaux épigastriques (donc vaisseaux en dedans), suit le cordon. Hernie directe = au-dessus de l'arcade, en dedans des vaisseaux épigastriques.",
      "_remarque": "L'HIOE est d'origine congénitale (persistance du canal péritonéo-vaginal) ou acquise, et expose au risque de descendre jusqu'au scrotum (hernie inguino-scrotale)."
    }
