    "explication": "Les hépatites B, C et D se transmettent par voie hématogène/sanguine et parentérale (B et D également par voie sexuelle). L'hépatite B est une MST majeure. L'hépatite A ne passe JAMAIS à la chronicité et ne donne jamais de cirrhose. (Note : Le corrigé officiel facultaire de l'épreuve a validé ABD).",
    "justifications": {
      "A": "Retenu dans la clé officielle de l'épreuve (EMD 2025 : ABD). En physiopathologie, VHA est féco-oral et VHB est hématogène/sexuel.",
      "B": "Vrai. Transmission parentérale et sanguine démontrée pour VHB, VHC et VHD.",
      "C": "Faux. Le VHA (et le VHE chez l'immunocompétent) ne passe jamais à la chronicité.",
      "D": "Vrai. Le virus B est présent dans les sécrétions génitales et constitue une IST majeure.",
      "E": "Faux. Le VHA guérit toujours spontanément sans passage à la cirrhose.",
      "_synthese": "Modes de transmission : VHA et VHE = entérique (eau/aliments, féco-orale). VHB, VHC, VHD = sanguine, sexuelle (VHB), materno-fœtale.",
      "_remarque": "La vaccination contre l'hépatite B prévient simultanément l'infection par le virus Delta (VHD) qui nécessite la membrane HBs."
    }
