      "B": "Retenu dans la clé officielle de l'épreuve (EMD 2025 : ABC). En oncologie, la thermoablation par radiofréquence est curative pour les nodules < 2-3 cm.",
      "C": "Proposition fausse (à cocher). Technique obsolète abandonnée au profit de la radiofréquence.",
      "D": "Proposition vraie (traitement curatif). Traite le cancer et la cirrhose sous-jacente.",
      "E": "Proposition vraie (traitement curatif). Résection réglée en marges saines.",
      "_synthese": "Traitements curatifs du CHC : Résection chirurgicale, transplantation hépatique (critères de Milan) et thermoablation percutanée (radiofréquence/micro-ondes). Traitement palliatif = Chimio-embolisation.",
      "_remarque": "La chimio-embolisation hépatique est contre-indiquée en cas de thrombose portale complète ou de décompensation hépatique Child C."
