      "B": "Vrai. Le Lopéramide freine le péristaltisme accéléré et prolonge le temps de contact muqueux.",
      "C": "Faux. La fuite d'eau et d'électrolytes coliques induit une HYPOkaliémie et une acidose métabolique.",
      "D": "Vrai. Excellente valeur prédictive négative pour écarter une maladie inflammatoire organique.",
      "E": "Faux. La définition formelle d'une diarrhée chronique est une durée supérieure à 4 semaines.",
      "_synthese": "Mécanismes des diarrhées chroniques : Osmotique (cesse au jeûne, trou osm > 100) ; Sécrétoire (persiste au jeûne, hypokaliémie) ; Motrice (post-prandiale, cède au Lopéramide, test rouge de carmin < 8h) ; Inflammatoire (calprotectine fécale élevée).",
      "_remarque": "Le trou osmotique fécal est calculé par la formule : 290 - 2 x (Na+ + K+ fécal)."
