    "explication": "La pancréatite chronique se définit par des lésions inflammatoires chroniques caractérisées par une fibrose progressive et irréversible du parenchyme pancréatique avec destruction des fonctions exocrines puis endocrines. Les douleurs épigastriques transfixiantes irradiant vers le dos et soulagées par l'antéflexion du tronc (position penchée en avant ou en chien de fusil) sont caractéristiques de la douleur pancréatique. Le scanner abdominal non injecté puis injecté est l'examen d'imagerie de première intention révélant les calcifications pancréatiques pathognomoniques et les anomalies canalaires. Les corticoïdes ne sont indiqués que dans la rare pancréatite auto-immune (type 1/2). L'alcool représente plus de 75-80% des causes.",
